define("block_iomad_mycourses/tab_preferences", ["jquery", "core/ajax", "core/custom_interaction_events", "core/notification"], function ($, Ajax, CustomEvents, Notification) {
    var selectors = {
        dropdownSelectors: '[data-action="changeselect"]'
    };

    var registerEventListeners = function (root) {
        if (!root || !root.length) {
            return;
        }

        if (root.data('iomad-mycourses-tab-preferences-registered')) {
            return;
        }
        root.data('iomad-mycourses-tab-preferences-registered', true);

        CustomEvents.define(root, [CustomEvents.events.activate]);
        root.on(CustomEvents.events.activate, "[data-bs-toggle='tab']", function (e) {
            var tabname = $(e.currentTarget).data('tabname');

            if (typeof window.history.pushState === "function") {
                window.history.pushState(null, null, '?iomad_mycoursestab=' + tabname);
            }

            var request = {
                methodname: 'core_user_update_user_preferences',
                args: {
                    preferences: [
                        {
                            type: 'block_iomad_mycourses_last_tab',
                            value: tabname
                        }
                    ]
                }
            };

            Ajax.call([request])[0].fail(Notification.exception);
        });

        root.find(selectors.dropdownSelectors).each(function () {
            this.addEventListener('click', function (event) {
                event.stopImmediatePropagation();
                var dropdownname = this.getAttribute('data-name');
                var dropdownvalue = this.getAttribute('data-value');
                var prefname = 'block_iomad_mycourses_user_' + dropdownname;
                var request = {
                    methodname: 'core_user_update_user_preferences',
                    args: {
                        preferences: [
                            {
                                type: prefname,
                                value: dropdownvalue
                            }
                        ]
                    }
                };

                Ajax.call([request])[0].fail(Notification.exception);
            });
        });
    };

    return {
        registerEventListeners: registerEventListeners
    };
});